def to_schema(self):
    from dataclasses import replace

    return super(StructureOverlay, replace(
        self,
        aliases={} if isinstance(self.aliases, Omitted) else self.aliases,
        alias_style=() if isinstance(self.alias_style, Omitted) else self.alias_style,
    )).to_schema()

def _merge_aliases(self, old, new):
    return {**old, **new}
